INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_tc_pb_basic_aggr_1d
partition (grass_region = ${grass_region},local_date = ${local_date}, local_hour)
select /*+ REBALANCE */ is_item_card
    ,user_id
    ,is_ads
    ,mapping_general
    ,shop_id
    ,item_id
    ,model_id
    ,sum(imp_cnt) imp_cnt
    ,sum(click_cnt) click_cnt
    ,sum(order_cnt) order_cnt
    ,sum(gmv) gmv
    ,sum(gmv_local) gmv_local
    ,sum(pc2_gmv) pc2_gmv
    ,sum(seller_gmv) seller_gmv
    ,sum(seller_gmv_local) seller_gmv_local
    ,local_hour
from (
select *
from    every_scene_data_raw_step2_${grass_region_without_quote}
union all
select
*
from video_and_live_data_raw_step2_${grass_region_without_quote}
union all
select  *
from    sr_data_raw_step2_${grass_region_without_quote}
union all
select  *
from    platform_data_raw_step2_${grass_region_without_quote}
)t1
group by is_item_card
        ,user_id
        ,is_ads
        ,mapping_general
        ,shop_id
        ,item_id
        ,model_id
        ,local_hour
;
